use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::Deserialize;
use std::sync::Mutex;
use std::fs::OpenOptions;
use std::io::Write;
use chrono::Utc;

#[derive(Deserialize, Clone)]
struct AuditEvent {
    action: String,
    resource: String,
    user_id: String,
    details: String,
}

struct AppState {
    log_file: Mutex<std::fs::File>,
    event_counter: Mutex<u64>,
}

/// Comprehensive sanitization for log output
/// Removes all known dangerous characters that could allow log injection
fn sanitize_log_field(input: &str) -> String {
    let mut result = String::with_capacity(input.len());
    for ch in input.chars() {
        match ch {
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\x0B' => result.push_str("\\v"),  // vertical tab
            '\x0C' => result.push_str("\\f"),  // form feed
            '\x00'..='\x08' | '\x0E'..='\x1F' => result.push_str("\\x"),  // other control chars
            '\u{0085}' => result.push_str("\\nel"),  // NEL (Next Line)
            '\u{2028}' => result.push_str("\\ls"),   // Line Separator
            '\u{2029}' => result.push_str("\\ps"),   // Paragraph Separator
            '|' => result.push('_'),
            '[' | ']' => result.push('_'),
            _ => result.push(ch),
        }
    }
    result
}

/// Validates that the action field contains only expected values
fn validate_action(action: &str) -> bool {
    matches!(action, "CREATE" | "READ" | "UPDATE" | "DELETE" | "LOGIN" | "LOGOUT" | "EXPORT")
}

/// Format a structured log line
fn format_log_entry(seq: u64, event: &AuditEvent, client_ip: &str) -> String {
    let timestamp = Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ");
    let safe_action = sanitize_log_field(&event.action);
    let safe_resource = sanitize_log_field(&event.resource);
    let safe_user = sanitize_log_field(&event.user_id);
    let safe_details = sanitize_log_field(&event.details);

    format!(
        "[{}] [SEQ:{:08}] [AUDIT] action={} | resource={} | user={} | ip={} | details={}",
        timestamp, seq, safe_action, safe_resource, safe_user, client_ip, safe_details
    )
}

async fn submit_audit_event(
    req: HttpRequest,
    data: web::Data<AppState>,
    body: web::Json<AuditEvent>,
) -> HttpResponse {
    let client_ip = req.peer_addr()
        .map(|addr| addr.ip().to_string())
        .unwrap_or_else(|| "unknown".to_string());

    let event = body.into_inner();

    if !validate_action(&event.action) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Invalid action type"
        }));
    }

    if event.user_id.len() > 128 || event.resource.len() > 256 || event.details.len() > 1024 {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Field length exceeded"
        }));
    }

    let seq = {
        let mut counter = data.event_counter.lock().unwrap_or_else(|e| e.into_inner());
        *counter += 1;
        *counter
    };

    let log_line = format_log_entry(seq, &event, &client_ip);

    {
        let mut file = data.log_file.lock().unwrap_or_else(|e| e.into_inner());
        let _ = writeln!(file, "{}", log_line);
    }

    HttpResponse::Ok().json(serde_json::json!({
        "status": "recorded",
        "sequence": seq
    }))
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open("/var/log/audit/events.log")?;

    let state = web::Data::new(AppState {
        log_file: Mutex::new(log_file),
        event_counter: Mutex::new(0),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/api/v1/audit", web::post().to(submit_audit_event))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
